import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem100 atribui alegações sem alterar título, preço ou afiliado',()=>{for(const [id,titulo] of [["mlMLB4741657351","Tênis Feminino Kolosh Confortável Macio Ziper Envio Rápido"],["mlMLB4748589927","Body Splash Masculino Vibration 200ml - Primacial Perfume Bergamota Fresco"],["mlMLB4748674769","Kit Body Splash Masculino Vibration E Blunn 200ml - Primacial Perfume Bergamota Limão"]]){const p={id,titulo,comentario:'anterior',preco:'preservar',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.notEqual(x.comentario,p.comentario);assert.equal(x.preco,p.preco);assert.equal(x.linkAfiliado,p.linkAfiliado);assert.equal(x.titulo,titulo);assert.deepEqual(correctProductData(x),x);}});
